{
  "title": "Discussion on tax filing, domain purchase, and app viability",
  "topics": [
    {
      "id": "tax-filing",
      "title": "Tax filing workaround",
      "claims": [
        {
          "text": "Giving 500 UAH to aunt Sveta to correct declarations can avoid large penalties, costing about 1000 UAH total.",
          "evidence": [1]
        },
        {
          "text": "The inspector previously approved declarations without review and was later reprimanded, prompting a re‑audit of all years.",
          "evidence": [1]
        }
      ]
    },
    {
      "id": "domain-calculator",
      "title": "Domain purchase and calculator need",
      "claims": [
        {
          "text": "If someone buys the calculator, there will be money for a domain.",
          "evidence": [4]
        },
        {
          "text": "The whole tax‑declaration procedure takes about an hour of Excel work per day, at most a day per month.",
          "evidence": [5, 6, 7]
        }
      ]
    },
    {
      "id": "web-app-profitability",
      "title": "Viability of a web‑based product",
      "claims": [
        {
          "text": "Web platforms are the simplest but far less profitable than Android/iOS; SEO is poor, no external traffic, and paywalls deter users, leading to near‑zero conversion.",
          "evidence": [11]
        },
        {
          "text": "Successful rapid delivery (under a week) using a cross‑platform stack like Flutter and copying popular ideas can work.",
          "evidence": [12]
        },
        {
          "text": "Igor's attempt to earn money with this approach seems unlikely to attract buyers.",
          "evidence": [17]
        },
        {
          "text": "LinkedIn audience for technical/managerial posts has dropped below 50 %.",
          "evidence": [18]
        }
      ]
    },
    {
      "id": "app-security",
      "title": "Security concerns of the proposed app",
      "claims": [
        {
          "text": "The calculator works only with UAH‑registered FOP; conversions must be done per day’s exchange rate.",
          "evidence": [19]
        },
        {
          "text": "The app’s bundle contains a hard‑coded promo‑code password offering 100 % discount.",
          "evidence": [20, 23]
        },
        {
          "text": "The source code likely contains the password, making it easy to hack.",
          "evidence": [21]
        }
      ]
    }
  ],
  "decisions": [],
  "openQuestions": [
    {
      "text": "What is the source code of the app, and can the password be found by searching it?",
      "evidence": [21]
    }
  ]
}
